// ---------- bank reconciliation ----------
let bankAcc = '';
function viewBank() {
    if (!hasFeature('bankRecon')) { $('#view').innerHTML = lockedPage('bankRecon'); return; }
    const banks = co.accounts.filter(a => a.group === 'bank');
    if (!banks.length) { $('#view').innerHTML = pageHead('Bank reconciliation', '') + `<div class="empty">Add a bank ledger first (Chart of accounts → New ledger → group "Bank Accounts").</div>`; return; }
    if (!banks.some(b => b.id === bankAcc)) bankAcc = banks[0].id;
    const lines = co.bankLines.filter(l => l.accId === bankAcc).sort((a, b) => a.date.localeCompare(b.date));
    const matchedV = new Set(lines.filter(l => l.vid).map(l => l.vid));
    const first = lines[0]?.date, last = lines.at(-1)?.date;
    const bookEnts = (book().entries.get(bankAcc) || []).filter(e => first && e.date >= first && e.date <= last && !matchedV.has(e.vid));
    const bookBal = last ? balance(bankAcc, last) : balance(bankAcc);
    const notPresented = sum(bookEnts.filter(e => e.cr), 'cr'), notCredited = sum(bookEnts.filter(e => e.dr), 'dr');
    $('#view').innerHTML = pageHead('Bank reconciliation', 'Import the bank statement; entries are matched automatically by amount and date. What is left is either missing from your books (create it in one click) or not yet cleared by the bank.',
        `<select onchange="bankAcc=this.value;route()">${banks.map(b => opt(b.id, b.name, bankAcc)).join('')}</select>`)
        + `<div class="card"><div class="row"><input type="file" id="bkFile" accept=".csv">${canEdit() ? `<button class="btn btn-p btn-sm" onclick="importBank()">Import statement</button><button class="btn btn-s btn-sm" onclick="autoMatch(true)">Auto-match</button>` : ''}<button class="btn btn-g btn-sm" onclick="download('bank-sample.csv', sampleBankCsv(), 'text/csv')">Sample CSV</button></div>
            <p class="note" style="margin-top:6px">CSV columns: Date, Description, Withdrawal (debit), Deposit (credit), Reference. Most Indian bank downloads work as they are.</p></div>
        ${last ? `<div class="card"><h2>Bank reconciliation statement as at ${fmtDate(last)}</h2><div class="tw"><table class="t"><tbody>
            <tr><td>Balance as per books</td><td class="n">${drcr(bookBal)}</td></tr>
            <tr><td>Add: cheques / payments issued but not yet debited by the bank</td><td class="n">${num(notPresented)}</td></tr>
            <tr><td>Less: deposits recorded but not yet credited by the bank</td><td class="n">${num(notCredited)}</td></tr>
            <tr><td>Less: bank entries not yet in the books (net)</td><td class="n">${num(sum(lines.filter(l => !l.vid), l => l.amt))}</td></tr>
            <tr class="grand"><td>Balance as per bank (for the imported period)</td><td class="n">${drcr(bookBal + notPresented - notCredited + sum(lines.filter(l => !l.vid), l => l.amt))}</td></tr></tbody></table></div></div>` : ''}
        <div class="card"><h2>Statement lines <span class="badge good">${lines.filter(l => l.vid).length} matched</span> <span class="badge warn">${lines.filter(l => !l.vid).length} open</span></h2><div class="tw"><table class="t"><thead><tr><th>Date</th><th>Description</th><th class="n">Withdrawal</th><th class="n">Deposit</th><th>Matched with</th><th></th></tr></thead><tbody>
        ${lines.map(l => `<tr><td>${fmtDate(l.date)}</td><td>${esc(l.desc)}</td>${amtCell(l.amt < 0 ? -l.amt : 0)}${amtCell(l.amt > 0 ? l.amt : 0)}<td>${l.vid ? `<a href="#/v/${l.vid}">${esc(vById(l.vid)?.no || '')}</a>` : '<span class="badge warn">Not in books</span>'}</td><td style="white-space:nowrap">${!canEdit() ? '' : l.vid ? `<button class="link" onclick="unmatch('${l.id}')">Unmatch</button>` : `<button class="link" onclick="createFromLine('${l.id}')">Create entry</button>`}</td></tr>`).join('') || '<tr><td colspan="6" class="muted" style="text-align:center;padding:20px">Import a statement to start.</td></tr>'}
        </tbody></table></div></div>
        ${bookEnts.length ? `<div class="card"><h2>In books, not in the statement</h2>${bookEnts.map(e => `<div class="note"><a href="#/v/${e.vid}">${esc(vById(e.vid).no)}</a> · ${fmtDate(e.date)} · ${e.dr ? 'deposit' : 'payment'} ${inr(e.dr || e.cr)}</div>`).join('')}</div>` : ''}`;
}
async function importBank() {
    const f = $('#bkFile').files[0];
    if (!f) return toast('Choose the statement CSV first.');
    try {
        const rows = csvParse(await f.text());
        const head = rows.shift().map(h => h.toLowerCase());
        const col = re => head.findIndex(h => re.test(h));
        const c = { d: col(/date/), n: col(/desc|narration|particular|remark/), w: col(/withdraw|debit|dr/), dp: col(/deposit|credit|cr/), a: col(/^amount/), r: col(/ref|cheque|chq/) };
        if (c.d < 0 || (c.a < 0 && (c.w < 0 || c.dp < 0))) throw new Error('Could not find Date and Withdrawal / Deposit (or Amount) columns.');
        let n = 0;
        rows.forEach(r => {
            const date = anyDateToISO(r[c.d]);
            if (!date) return;
            const amt = c.a >= 0 ? r2(String(r[c.a]).replace(/,/g, '')) : r2(Number(String(r[c.dp] || 0).replace(/,/g, '')) - Number(String(r[c.w] || 0).replace(/,/g, '')));
            if (!amt) return;
            const desc = (r[c.n] || '').trim(), ref = c.r >= 0 ? (r[c.r] || '').trim() : '';
            if (co.bankLines.some(x => x.accId === bankAcc && x.date === date && x.amt === amt && x.desc === desc)) return;   // skip duplicates on re-import
            co.bankLines.push({ id: uid('bl'), accId: bankAcc, date, desc, amt, ref, vid: '' });
            n++;
        });
        audit('Bank statement imported', { entity: 'Bank', ref: accById(bankAcc).name, after: `${n} new lines` });
        saveCo();
        const m = autoMatch(false);
        toast(`${n} lines imported, ${m} matched automatically.`);
        route();
    } catch (e) { alert(e.message); }
}
function autoMatch(show) {
    const used = new Set(co.bankLines.filter(l => l.vid).map(l => l.vid));
    const ents = book().entries.get(bankAcc) || [];
    let n = 0;
    co.bankLines.filter(l => l.accId === bankAcc && !l.vid).forEach(l => {
        const cand = ents.filter(e => !used.has(e.vid) && r2(e.dr - e.cr) === l.amt && Math.abs(daysBetween(e.date, l.date)) <= 5)
            .sort((a, b) => Math.abs(daysBetween(a.date, l.date)) - Math.abs(daysBetween(b.date, l.date)));
        if (cand[0]) { l.vid = cand[0].vid; used.add(cand[0].vid); n++; }
    });
    if (n) { audit('Bank lines auto-matched', { entity: 'Bank', ref: accById(bankAcc).name, after: `${n} matched` }); saveCo(); }
    if (show) { toast(`${n} line(s) matched.`); route(); }
    return n;
}
function unmatch(id) { const l = co.bankLines.find(x => x.id === id); l.vid = ''; audit('Bank line unmatched', { entity: 'Bank', ref: l.desc }); saveCo(); route(); }
function createFromLine(id) {
    const l = co.bankLines.find(x => x.id === id);
    const guess = co.contacts.find(c => l.desc.toLowerCase().includes(c.name.toLowerCase().split(' ')[0])) || null;
    const rule = co.rules.find(r => l.desc.toLowerCase().includes(r.word));
    modal({
        title: `${l.amt > 0 ? 'Receipt' : 'Payment'} from bank line`,
        body: `<p class="note" style="margin-bottom:10px">${fmtDate(l.date)} · ${esc(l.desc)} · <b>${inr(Math.abs(l.amt))}</b></p><div id="clErr"></div>
            <label class="f">${l.amt > 0 ? 'Received from' : 'Paid to'}<select id="cl_who">${ledgerOptions(guess?.id || rule?.acc || '', x => !['bank', 'cash'].includes(x.group))}</select></label>
            <label class="chk" style="margin-top:10px"><input type="checkbox" id="cl_rule"> Remember: lines containing "<input id="cl_word" style="width:140px;padding:3px 6px" value="${esc(l.desc.split(/\s+/)[0] || '')}">" go to this ledger</label>`,
        foot: `<button class="btn btn-s" onclick="closeModal()">Cancel</button><button class="btn btn-p" id="clOk">Create & match</button>`,
        onOpen: () => $('#clOk').onclick = () => {
            const who = ledgerOf(val('cl_who'));
            if (!who) return showErr('#clErr', 'Choose the ledger.');
            try {
                const v = saveVoucher({ type: l.amt > 0 ? 'RC' : 'PY', date: l.date, accountId: l.accId, partyId: who.kind === 'contact' ? who.id : '', ledgerId: who.kind === 'account' ? who.id : '', amount: Math.abs(l.amt), refNo: l.ref, narration: l.desc }, { source: 'Bank statement' });
                if (who.kind === 'contact') { const bills = openBills(who.id, l.amt > 0 ? 'SI' : 'PB'); let left = Math.abs(l.amt); v.alloc = []; bills.forEach(b => { if (left <= 0) return; const a = r2(Math.min(left, b.due)); v.alloc.push({ vid: b.v.id, amt: a }); left = r2(left - a); }); }
                l.vid = v.id;
                if (chk('cl_rule') && val('cl_word')) co.rules.push({ word: val('cl_word').toLowerCase(), acc: who.id });
                saveCo(); closeModal(); toast(`${v.no} created and matched.`); route();
            } catch (e) { showErr('#clErr', e); }
        }
    });
}
function sampleBankCsv() {
    const ents = (book().entries.get(bankAcc) || []).slice(-8);
    const rows = ents.map(e => [ddmmyyyy(e.date, '/'), (vById(e.vid).narration || ledgerOf(vById(e.vid).partyId || vById(e.vid).ledgerId)?.name || 'Transfer').slice(0, 40), e.cr ? e.cr : '', e.dr ? e.dr : '', vById(e.vid).refNo || '']);
    rows.push([ddmmyyyy(todayISO(), '/'), 'BANK CHARGES SMS ALERT', 59, '', '']);
    rows.push([ddmmyyyy(todayISO(), '/'), 'INT CREDIT SAVINGS', '', 412, '']);
    return toCSV([['Date', 'Description', 'Withdrawal', 'Deposit', 'Reference'], ...rows]);
}

