const REMINDER_DEFAULTS = {
    waReminder: 'Dear {customer}, a friendly reminder: {amount} is due against {invoices}. Kindly arrange payment{upi}. – {company}',
    waInvoice: 'Dear {customer}, please find {invoices} for {amount}, due by {due}. – {company}',
    waReceipt: 'Dear {customer}, we have received {amount}. Thank you! – {company}'
};
function fillTemplate(key, vals) {
    const t = co.settings.prefs?.[key] || REMINDER_DEFAULTS[key];
    return t.replace(/\{(\w+)\}/g, (m, k) => vals[k] ?? '');
}
function setProfile(key, value) {
    if (!isAdmin()) return toast('Only the owner can change settings.');
    value = typeof value === 'string' ? value.trim() : value;
    if (['tan', 'respPan'].includes(key)) value = value.toUpperCase();
    if (key === 'tan' && value && !/^[A-Z]{4}\d{5}[A-Z]$/.test(value)) { toast('TAN must look like CHEA12345B.'); return route(); }
    if (key === 'respPan' && value && !panValid(value)) { toast('PAN is not valid.'); return route(); }
    if (key === 'respMobile' && value && !/^[6-9]\d{9}$/.test(value)) { toast('Mobile must be 10 digits.'); return route(); }
    if (key === 'upi' && value && !/^[\w.\-]{2,}@[a-zA-Z]{2,}$/.test(value)) { toast('UPI ID must look like name@bank.'); return route(); }
    if (key === 'aato') value = Number(value) || 0;
    if (key === 'gstFreq' && value === 'quarterly' && (Number(co.profile.aato) || 0) > 50000000) { toast('QRMP is only for turnover up to ₹5 crore.'); return route(); }
    const old = co.profile[key];
    if (old === value) return;
    co.profile[key] = value;
    audit('Setting changed', { entity: 'Settings', ref: key, before: ['logo', 'signature'].includes(key) ? (old ? 'image' : '') : String(old ?? ''), after: ['logo', 'signature'].includes(key) ? (value ? 'new image' : 'removed') : String(value) });
    saveCo(); route(); toast('Saved.');
}
function setPref(key, value) {
    if (!isAdmin()) return toast('Only the owner can change settings.');
    const P = co.settings.prefs ||= {};
    if (typeof value === 'string' && /Days$|largeJv|defaultGst|remindAfter|idleMinutes/.test(key)) value = Number(value) || 0;
    if (key === 'idleMinutes') value = Math.min(240, Math.max(5, value));
    audit('Preference changed', { entity: 'Settings', ref: key, before: String(P[key] ?? ''), after: String(value) });
    P[key] = value; saveCo(); toast('Saved.');
}
function pickImage(key) {
    const input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/*';
    input.onchange = () => {
        const f = input.files[0];
        if (!f || f.size > 2 * 1024 * 1024) return toast('Choose an image under 2 MB.');
        const r = new FileReader();
        r.onload = () => { const img = new Image(); img.onload = () => { const c = document.createElement('canvas'); const k = Math.min(1, 360 / Math.max(img.width, img.height)); c.width = img.width * k; c.height = img.height * k; c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); setProfile(key, c.toDataURL('image/png')); }; img.src = r.result; };
        r.readAsDataURL(f);
    };
    input.click();
}
const IMPORT_COLS = {
    customers: ['Name', 'GSTIN', 'PAN', 'State code', 'City', 'Mobile', 'Email', 'Credit days', 'Opening receivable'],
    vendors: ['Name', 'GSTIN', 'PAN', 'State code', 'City', 'Mobile', 'Email', 'Credit days', 'Opening payable', 'MSME (Y/N)', 'TDS code'],
    items: ['Name', 'Type (goods/service)', 'HSN/SAC', 'GST rate', 'Unit', 'Sale rate', 'Purchase rate', 'Opening qty', 'Opening value']
};
function importTemplate(kind) {
    const ex = { customers: ['Lakshmi Traders', '33AAFFL1234K1Z5', '', '33', 'Chennai', '9840000000', '', '30', '0'], vendors: ['Sri Balaji Suppliers', '', 'ABCPB1234K', '33', 'Madurai', '', '', '30', '0', 'Y', '1027'], items: ['Switch 6A', 'goods', '853650', '18', 'NOS', '45', '30', '100', '3000'] }[kind];
    return toCSV([IMPORT_COLS[kind], ex]);
}
async function runImport(kind) {
    const f = $(`#imp_${kind}`).files[0];
    if (!f) return toast('Choose the CSV file first.');
    const rows = csvParse(await f.text());
    rows.shift();
    let ok = 0;
    const errs = [];
    const codeToKey = c => Object.keys(TDS_SECTIONS).find(k => TDS_SECTIONS[k].code === String(c).trim() || k === String(c).trim()) || '';
    rows.forEach((r, i) => {
        const c = x => (r[x] || '').trim();
        try {
            if (kind === 'items') saveItem({ name: c(0), type: /serv/i.test(c(1)) ? 'service' : 'goods', hsn: c(2), gstRate: Number(c(3)), unit: (c(4) || 'NOS').toUpperCase(), rate: Number(c(5)) || 0, purchaseRate: Number(c(6)) || 0, openQty: Number(c(7)) || 0, openValue: Number(c(8)) || 0, trackStock: !/serv/i.test(c(1)) });
            else {
                const vend = kind === 'vendors';
                saveContact({ type: vend ? 'vendor' : 'customer', name: c(0), gstin: c(1), pan: c(2), state: c(3) || c(1).slice(0, 2) || companyState(), city: c(4), phone: c(5), email: c(6), creditDays: Number(c(7)) || 30, openDr: vend ? 0 : Number(c(8)) || 0, openCr: vend ? Number(c(8)) || 0 : 0, msme: vend && /^y/i.test(c(9)), tdsSection: vend ? codeToKey(c(10)) : '' });
            }
            ok++;
        } catch (e) { errs.push(`Row ${i + 2} (${r[0] || 'blank'}): ${e.message.replace(/\n/g, '; ')}`); }
    });
    audit('Import', { entity: 'Settings', ref: kind, after: `${ok} imported, ${errs.length} skipped` });
    $('#impOut').innerHTML = `<div class="${errs.length ? 'warns' : 'note'}"><b>${ok} ${kind} imported.</b>${errs.length ? `<br>${errs.length} skipped:<br>${errs.slice(0, 30).map(esc).join('<br>')}` : ''}</div>`;
}
function savePrefixes() {
    const before = JSON.stringify(co.settings.prefixes);
    Object.keys(VTYPES).forEach(k => { const v = val('px_' + k).toUpperCase().replace(/[^A-Z0-9-]/g, ''); if (v) co.settings.prefixes[k] = v; });
    audit('Number prefixes changed', { entity: 'Settings', before, after: JSON.stringify(co.settings.prefixes) });
    saveCo(); toast('Saved. New prefixes apply to new vouchers.');
}
async function saveLock() {
    const d = val('lockDate');
    if (d && d > todayISO()) return alert('The lock date cannot be in the future.');
    const reason = await ask({ title: 'Change lock date', message: d ? `Lock all entries up to ${fmtDate(d)}?` : 'Remove the lock?', input: 'Reason', ok: 'Save' });
    if (reason === null) return;
    audit('Lock date changed', { entity: 'Settings', before: co.settings.lockDate || 'none', after: d || 'none', reason });
    co.settings.lockDate = d; saveCo(); route();
}
function userForm(id) {
    const u = id ? meta.users.find(x => x.id === id) : { role: 'accountant', companies: [co.id], active: true };
    modal({
        title: id ? `Edit ${u.name}` : 'Add user',
        body: `<div id="usErr"></div><div class="fg" style="grid-template-columns:1fr 1fr">
            <label class="f">Name<input id="us_name" value="${esc(u.name)}"></label><label class="f">Username<input id="us_user" value="${esc(u.username)}" ${id ? 'readonly' : ''}></label>
            <label class="f">Role<select id="us_role">${Object.entries(ROLES).map(([k, l]) => opt(k, l, u.role)).join('')}</select></label>
            <label class="f">Password ${id ? '<span class="hint">blank = unchanged</span>' : `(${MIN_PASSWORD}+ characters)`}<input id="us_pass" type="password" autocomplete="new-password"></label>
            <label class="f wide">Companies <span class="hint">Hold Ctrl / ⌘ to pick several</span><select id="us_cos" multiple size="4">${opt('all', 'All companies', u.companies === 'all' ? 'all' : '')}${meta.companies.map(c => `<option value="${c.id}" ${u.companies !== 'all' && (u.companies || []).includes(c.id) ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></label>
            <label class="chk"><input type="checkbox" id="us_act" ${u.active !== false ? 'checked' : ''}> Active</label></div>`,
        foot: `<button class="btn btn-s" onclick="closeModal()">Cancel</button><button class="btn btn-p" id="usOk">Save</button>`,
        onOpen: () => $('#usOk').onclick = () => {
            const E = [];
            const name = val('us_name'), user = val('us_user').toLowerCase(), pass = $('#us_pass').value, role = val('us_role');
            const cos = [...$('#us_cos').selectedOptions].map(o => o.value);
            if (!name) E.push('Name is required.');
            if (!/^[a-z0-9._-]{3,30}$/.test(user)) E.push('Username: 3–30 letters or digits.');
            if (!id && meta.users.some(x => x.username === user)) E.push('Username is taken.');
            if (!id && chk('us_act') && limitReached('users')) E.push(`Your ${PLANS[currentPlan()].name} plan allows ${planLimits().users} active user(s). Upgrade in Plan & billing.`);
            if (role === 'auditor' && !hasFeature('auditor')) E.push('The auditor role is in the Professional plan.');
            if ((!id || pass) && pass.length < MIN_PASSWORD) E.push(`Password must be at least ${MIN_PASSWORD} characters.`);
            if (!cos.length) E.push('Choose at least one company.');
            if (id === me.id && (role !== 'admin' || !chk('us_act'))) E.push('You cannot remove your own admin access.');
            if (E.length) { const e = new Error(); e.list = E; return showErr('#usErr', e); }
            const before = id ? `${u.role} · ${u.active !== false ? 'active' : 'disabled'}` : '';
            Object.assign(u, { name, username: user, role, companies: cos.includes('all') ? 'all' : cos, active: chk('us_act') });
            if (pass) { u.salt = randomHex(16); u.hash = hashPassword(pass, u.salt); }
            if (!id) { u.id = uid('u'); u.created = new Date().toISOString(); meta.users.push(u); }
            auditMeta(id ? 'User changed' : 'User added', { entity: 'User', ref: user, before, after: `${ROLES[role]} · ${chk('us_act') ? 'active' : 'disabled'}${pass ? ' · password set' : ''}` });
            closeModal(); route(); toast('User saved.');
        }
    });
}
async function exportAll() {
    const data = { app: 'we-create-erp', version: APP_VERSION, at: new Date().toISOString(), meta, companies: {}, files: {} };
    meta.companies.forEach(c => { data.companies[c.id] = loadCo(c.id); });
    for (const c of Object.values(data.companies)) for (const v of c?.vouchers || []) if (v.attachment) {
        try { const f = await files.get(`att:${v.id}`); if (f) data.files[v.id] = await new Promise(r => { const fr = new FileReader(); fr.onload = () => r(fr.result); fr.readAsDataURL(f); }); } catch (e) { /* skip */ }
    }
    auditMeta('Backup downloaded', { entity: 'System', ref: `${meta.companies.length} companies` });
    download(`we-create-erp-backup-${todayISO()}.json`, JSON.stringify(data), 'application/json');
}
async function importAll() {
    const f = $('#rsFile').files[0];
    if (!f) return toast('Choose the backup file.');
    let data;
    try { data = JSON.parse(await f.text()); } catch (e) { return alert('Not a valid backup file.'); }
    if (data.app !== 'we-create-erp') return alert('This is not a We Create ERP backup.');
    if (!await ask({ title: 'Restore backup', message: `Replace everything in this browser with the backup from ${new Date(data.at).toLocaleString('en-IN')}? You will need to sign in again.`, ok: 'Restore', danger: true })) return;
    Object.keys(localStorage).filter(k => k.startsWith('wcerp.')).forEach(k => localStorage.removeItem(k));
    Object.entries(data.companies).forEach(([id, c]) => c && safeSet(coKey(id), JSON.stringify(c)));
    meta = data.meta;
    auditPush(meta.audit, 'Backup restored', { entity: 'System', ref: data.at });
    saveMeta();
    for (const [vid, url] of Object.entries(data.files || {})) { try { await files.put(`att:${vid}`, await (await fetch(url)).blob()); } catch (e) { /* skip */ } }
    try { sessionStorage.removeItem('wcerp.session'); } catch (e) { /* ignore */ }
    location.reload();
}
async function removeCompany() {
    const name = await ask({ title: 'Remove company', message: `Type the company name to remove "${co.profile.name}" and all its data from this browser.`, input: 'Company name', ok: 'Remove', danger: true });
    if (name === null) return;
    if (name !== co.profile.name) return alert('The name did not match. Nothing was removed.');
    auditMeta('Company removed from this browser', { entity: 'Company', ref: co.profile.name });
    localStorage.removeItem(coKey(co.id));
    meta.companies = meta.companies.filter(c => c.id !== co.id);
    saveMeta(); co = null; go('#/companies');
}
